// Grammar, listening and reading content. Data comes from data/content.js (window.N3_GRAMMAR / N3_LISTENING /
// N3_READING), generated by tools/build-content.py from data/grammar-*.json, listening-*.json, reading-*.json.
(function () {
  'use strict';
  const N3 = window.N3;

  N3.CONTENT_META = window.N3_CONTENT_META || { grammar: 0, listening: 0, reading: 0 };

  // ---------- grammar: 10 patterns per unit ----------
  N3.G_PER_UNIT = 10;
  N3.FREE_G_UNITS = 2;        // grammar units 1–2 free (same rule as vocabulary units 1–2)
  N3.GRAMMAR = (Array.isArray(window.N3_GRAMMAR) ? window.N3_GRAMMAR : [])
    .filter(g => g && g.id && g.pattern && Array.isArray(g.examples))
    .map((g, i) => Object.assign({}, g, { unit: Math.floor(i / N3.G_PER_UNIT) + 1, _i: i, no: i + 1 }));
  N3.G_BY_ID = Object.fromEntries(N3.GRAMMAR.map(g => [g.id, g]));
  N3.G_UNITS = [...new Set(N3.GRAMMAR.map(g => g.unit))];
  N3.gUnitItems = u => N3.GRAMMAR.filter(g => g.unit === u);
  N3.isGUnitOpen = u => N3.state.premium || u <= N3.FREE_G_UNITS;
  N3.openGrammar = () => N3.GRAMMAR.filter(g => N3.isGUnitOpen(g.unit));

  // ---------- listening / reading ----------
  N3.FREE_LISTENING = 10;     // questions 1–10 free
  N3.FREE_READING = 5;        // passages 1–5 free
  N3.LISTENING = (Array.isArray(window.N3_LISTENING) ? window.N3_LISTENING : []).map((x, i) => Object.assign({}, x, { _i: i, no: i + 1 }));
  N3.READING = (Array.isArray(window.N3_READING) ? window.N3_READING : []).map((x, i) => Object.assign({}, x, { _i: i, no: i + 1 }));
  N3.L_BY_ID = Object.fromEntries(N3.LISTENING.map(x => [x.id, x]));
  N3.R_BY_ID = Object.fromEntries(N3.READING.map(x => [x.id, x]));
  N3.isListenOpen = x => N3.state.premium || x._i < N3.FREE_LISTENING;
  N3.isReadOpen = x => N3.state.premium || x._i < N3.FREE_READING;
  N3.openListening = () => N3.LISTENING.filter(N3.isListenOpen);
  N3.openReading = () => N3.READING.filter(N3.isReadOpen);
  N3.L_SET = 10;              // listening is grouped in sets of 10 on the list screen

  // Next listening questions for a practice round: unanswered first, then last-answer-wrong, then the rest.
  N3.nextListening = n => {
    const st = N3.state.stats.listen;
    const pool = N3.openListening();
    const rank = x => (!st[x.id] ? 0 : st[x.id].ok ? 2 : 1);
    return pool.slice().sort((a, b) => rank(a) - rank(b) || a._i - b._i).slice(0, n);
  };
  N3.nextReading = () => {
    const st = N3.state.stats.read;
    const pool = N3.openReading();
    const rank = x => (!st[x.id] ? 0 : st[x.id].r < st[x.id].t ? 1 : 2);
    return pool.slice().sort((a, b) => rank(a) - rank(b) || a._i - b._i)[0] || null;
  };

  // ---------- JLPT scoring sections ----------
  // JLPT N3 reports three scoring sections, each 0–60: Language knowledge (vocabulary + grammar), Reading,
  // Listening. Pass = total >= 95/180 AND every section >= 19.
  N3.SECTIONS = {
    lk: { name: 'Language knowledge', sub: 'Vocabulary and grammar', jp: '言語知識（文字・語彙・文法）' },
    rd: { name: 'Reading', sub: 'Short passages', jp: '読解' },
    ls: { name: 'Listening', sub: 'Conversations', jp: '聴解' },
  };
  N3.SEC_MAX = 60;
  N3.SEC_CUTOFF = 19;
  N3.PASS_TOTAL = 95;
  N3.TOTAL_MAX = 180;
  N3.EST_MIN_ANSWERS = 10;

  // Estimate from the recent answers of a section (quizzes, practice and mock tests): accuracy x 60.
  N3.sectionEstimate = sec => {
    const s = N3.state.stats.sec[sec] || '';
    const n = s.length;
    const right = (s.match(/1/g) || []).length;
    const score = n ? Math.round((right / n) * N3.SEC_MAX) : null;
    return { n, right, score, enough: n >= N3.EST_MIN_ANSWERS };
  };
  // Scale a raw section result (right of total) to the 0–60 band.
  N3.scale60 = (r, t) => (t ? Math.round((r / t) * N3.SEC_MAX) : 0);
})();
